style.css:
@-moz-document url-prefix("https://www.lorwolf.com/Seasonal") {
/* Keep Party Accordion always open */
.partyAccordionContainer {
    /* remove the closed class effect */
    height: auto !important;
    overflow: visible !important;
}

.partyAccordionContainer.closed {
    /* neutralize the closed styling */
    height: auto !important;
    overflow: visible !important;
}

.partyAccordionContentContainer {
    height: auto !important;
    overflow: visible !important;
    display: block !important;
    padding: 8px 12px !important; /* adds a little breathing room */
}

.partyAccordionTitle .glyphicon-chevron-down {
    display: none !important; /* hide down arrow */
}

.partyAccordionTitle .glyphicon-chevron-up {
    display: inline-block !important; /* show up arrow */
}
}
